import{z as i,x as s,o as e,c as l,q as t,j as n,D as E,d as A,s as B,S as o}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"开源框架对照与收束","description":"","frontmatter":{"title":"开源框架对照与收束","date":"2026-09-18T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/bf-opensource-map.md","filePath":"quant/bf-opensource-map.md","lastUpdated":1791413859000}'),p={name:"quant/bf-opensource-map.md"};function d(f,a,u,h,b,m){const r=s("Mermaid");return e(),l("div",null,[a[2]||(a[2]=t('<h1 id="开源框架对照与收束" tabindex="-1">开源框架对照与收束 <a class="header-anchor" href="#开源框架对照与收束" aria-label="Permalink to &quot;开源框架对照与收束&quot;">​</a></h1><div class="epigraph"><p>选框架不是数功能清单，是决定七个器官里哪几个外包、哪几个自己养：成交模拟与风控闸门，几乎总该自己养。</p><footer>—— 据 Microsoft Qlib、vn.py、ABIDES 与 kdb+ 的公开文档对照整理</footer></div><p><a href="/quant/bf-framework-testing">上一课</a>给了验收框架的测试体系。本课按第一课的解剖图对照四个谱系——研究向量化平台、事件驱动交易框架、代理仿真器、列式行情引擎——读出各自的强器官与空缺，回答「自建还是采用」。本课程到此收束。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>采用一个框架，等于默认接受它的全部隐含值：成交假设、时钟语义、试验计数与作者所在市场的规则。A 股的 T+1、涨跌停与竞价语义在上游框架里常常缺席，缺口常被使用者在策略层打补丁——补丁绕过引擎，测试也罩不住它。反过来一切都自建，就把事件循环与状态机这些久经实盘检验的商品代码重写一遍，省下的依赖换成自己维护的缺陷。缺口是决策标准：哪几个器官是商品，哪几个器官编码了你独有的场所规则与资金约束。</p><h3 id="四个谱系按解剖图对号" tabindex="-1">四个谱系按解剖图对号 <a class="header-anchor" href="#四个谱系按解剖图对号" aria-label="Permalink to &quot;四个谱系按解剖图对号&quot;">​</a></h3><p><strong>研究向量化平台</strong>以 Microsoft Qlib 为代表：点时数据层、模型插槽与实验记录齐备，回测偏日频向量化，成交假设轻；强在数据与研究侧器官，事件侧留白，执行须另接事件引擎（见<a href="/quant/qlib-quant">Microsoft Qlib</a>）。<strong>事件驱动交易框架</strong>以 vn.py 为代表：事件引擎加网关适配把国内柜台差异收成统一对象，回测与实盘共享状态机、撮合器可插拔；强在交易控制面，微观结构保真度不在默认回调里（见<a href="/quant/vnpy-framework">vn.py 交易框架</a>）。<strong>代理仿真器</strong>以 ABIDES 为代表：离散事件内核让延迟、撮合规则与反事实代理成为一等对象，回答的是市场设计与多代理问题，不是单策略协议回测（见<a href="/quant/abides-simulation">ABIDES 事件驱动仿真</a>）。<strong>列式行情引擎</strong>以 kdb+/q 为代表：tick 带宽与 as-of 连接把计算搬到数据旁边，是引擎的存储侧底座而非回测器本身（见<a href="/quant/kdb-plus">kdb+ 与 q</a>）。</p>',7)),(e(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-19",class:"mermaid",graph:"flowchart%20TD%0A%20%20QL%5B%22Qlib%20%E7%A0%94%E7%A9%B6%E5%B9%B3%E5%8F%B0%22%5D%20--%3E%20ORG%5B%22%E6%95%B0%E6%8D%AE%E7%AB%AF%E5%8F%A3%20%E8%B4%A6%E6%9C%AC%20%E8%AE%B0%E5%BD%95%E5%99%A8%22%5D%0A%20%20VN%5B%22vn.py%20%E4%BA%A4%E6%98%93%E6%A1%86%E6%9E%B6%22%5D%20--%3E%20ORG2%5B%22%E6%97%B6%E9%92%9F%20%E7%AD%96%E7%95%A5%E7%AB%AF%E5%8F%A3%20%E8%AE%A2%E5%8D%95%E7%8A%B6%E6%80%81%E6%9C%BA%22%5D%0A%20%20AB%5B%22ABIDES%20%E4%BB%A3%E7%90%86%E4%BB%BF%E7%9C%9F%22%5D%20--%3E%20ORG3%5B%22%E4%BA%8B%E4%BB%B6%E5%85%A8%E5%BA%8F%20%E6%92%AE%E5%90%88%E8%A7%84%E5%88%99%20%E5%BB%B6%E8%BF%9F%22%5D%0A%20%20KD%5B%22kdb%2B%20%E5%88%97%E5%BC%8F%E5%BC%95%E6%93%8E%22%5D%20--%3E%20ORG4%5B%22%E6%95%B0%E6%8D%AE%E5%AD%98%E5%82%A8%20as-of%20%E6%9F%A5%E8%AF%A2%22%5D%0A%20%20ORG%20--%3E%20OWN%5B%22%E8%87%AA%E5%B7%B1%E5%85%BB%20%E6%88%90%E4%BA%A4%E6%A8%A1%E6%8B%9F%20%E9%A3%8E%E6%8E%A7%E9%97%B8%E9%97%A8%20%E6%B5%8B%E8%AF%95%22%5D%0A%20%20ORG2%20--%3E%20OWN%0A%20%20ORG3%20--%3E%20OWN%0A%20%20ORG4%20--%3E%20OWN%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>采用与自建按器官分账。可以外包的：事件循环、行情适配、订单状态机、数据存储——这些是商品代码，社区替你踩过坑，测试体系照常适用。应当自己养的：成交模拟器（它编码你所在场所的优先规则与自己的冲击，是乐观偏差的入口，见<a href="/quant/bf-fill-simulation-deep">成交模拟的深化</a>）；风控闸门（资金与限额是公司事实）；扫描的结果库与试验计数（<a href="/quant/bf-param-sweep-arch">参数扫描的架构</a>的多重检验纪律没法外包）。验收照上一课的尺子：黄金重放、泄漏检测、并行一致三条达标；功能清单再长也不算框架，只算演示集。</p><p><span class="marginnote">框架默认值是最常缺席的声明：用框架回测五年的人，未必说得出它的默认延迟、队列位置与费用。验收时把默认值抄成一页纸——说不清默认值的回测，审计时等于没有成本模型。</span></p><p><span class="marginnote">成交模拟器就是用你所在场所的撮合规则来回答「这一笔能不能成交、成交在哪个价位」的部件。框架自带的撮合器常默认「挂单就能吃到」，在流动性薄的合约上会高估成交、低估冲击——乐观偏差从这里进账，后面的夏普再漂亮也不可信。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>对照的机制收获是把「框架差异」翻译成「器官差异」：框架间的性能之争，多是各自强器官不同——Qlib 的快在研究层数据管道，vn.py 的价值在控制面统一，ABIDES 的贡献在延迟与反事实建模，kdb+ 的带宽在存储侧。混合使用因此有清晰接缝：kdb+ 或列存平台做存储与 as-of（<a href="/quant/de-tsdb-selection">时序数据库的选型</a>照用），Qlib 类平台做信号研究，自养的事件引擎做定案，vn.py 类框架做实盘控制面——每条接缝只传数据与信号，不共享可变状态。</p>',6)),(e(),n(o,null,{default:E(()=>[B(r,{id:"mermaid-38",class:"mermaid",graph:"flowchart%20LR%0A%20%20K%5B%22kdb%2B%20%E5%88%97%E5%BC%8F%E5%AD%98%E5%82%A8%22%5D%20--%3E%7C%22as-of%20%E5%AF%B9%E9%BD%90%E8%A1%8C%E6%83%85%22%7C%20Q%5B%22Qlib%20%E7%B1%BB%E4%BF%A1%E5%8F%B7%E7%A0%94%E7%A9%B6%22%5D%0A%20%20Q%20--%3E%7C%22%E5%9B%A0%E5%AD%90%E4%B8%8E%E4%BF%A1%E5%8F%B7%22%7C%20E%5B%22%E8%87%AA%E5%85%BB%E4%BA%8B%E4%BB%B6%E5%BC%95%E6%93%8E%20%E5%AE%9A%E6%A1%88%E5%9B%9E%E6%B5%8B%22%5D%0A%20%20E%20--%3E%7C%22%E9%80%9A%E8%BF%87%E9%AA%8C%E6%94%B6%E7%9A%84%E7%AD%96%E7%95%A5%22%7C%20V%5B%22vn.py%20%E7%B1%BB%E5%AE%9E%E7%9B%98%E6%8E%A7%E5%88%B6%E9%9D%A2%22%5D%0A%20%20V%20--%3E%7C%22%E6%88%90%E4%BA%A4%E4%B8%8E%E6%8C%81%E4%BB%93%E5%9B%9E%E6%8A%A5%22%7C%20K%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<p><span class="marginnote">「接缝只传数据与信号，不共享可变状态」可以想象成外卖平台与餐厅：平台只递订单和地址，不伸手进后厨动锅铲。一旦两个系统共用同一份可变的持仓或订单状态，谁改了一半、谁读到旧值就说不清——回测与实盘对不上账，多半坏在这里。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>对照会过期：许可、版本与生态三年一变，本课留的是对照方法而不是排名。代理仿真回答的是市场设计问题，别拿它替代协议回测；商用列式引擎的许可与人才成本要计入决策；上游缺席的中国场所规则，贡献回去或带声明的补丁分叉，别静默改。至此九课走完：解剖给出器官与不变量，取舍给出两层分工，成交与多资产给出保真度和规模，扫描与并行给出吞吐和纪律，诊断与测试给出证据和守护，对照给出采用与自建的分账——回测框架设计的全部内容，就是把回测语义做成可维护、可审计、可重放的软件。本课程到此收束。</p><p><span class="marginnote">初学者容易以为这张对照表是「排名」，照着买第一名就能用三年。实际上框架生态随许可、版本与维护者变动，一个更新停在两年前的框架，往往比功能少一截但维护活跃的框架更危险——选型看的是器官缺口与你愿意养哪些，不是总分。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>四谱系按解剖图对号：研究平台、交易框架、代理仿真、列式引擎，各有强器官与留白。</li><li>可外包：事件循环、状态机、存储、适配；应自养：成交模拟、风控闸门、结果库与试验计数。</li><li>验收看三条：黄金重放、泄漏检测、并行一致性；功能清单不替代它们。</li><li>框架默认值（延迟、队列、费用）必须抄录声明；说不清默认值等于没有成本模型。</li><li>课程收束：九课一条线——把回测语义做成可维护、可审计、可重放的软件。</li><li>出处：Microsoft Qlib、vn.py、ABIDES、kdb+ 公开文档；站内<a href="/quant/bf-event-driven-anatomy">事件驱动框架的解剖</a>、<a href="/quant/bf-framework-testing">框架的测试</a>各课。</li></ul>',6))])}const D=i(p,[["render",d]]);export{_ as __pageData,D as default};
